<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import * as echarts from 'echarts'
import { statusNames } from '../composables'
const props=defineProps<{summary:any}>(), trend=ref<HTMLDivElement|null>(null), distribution=ref<HTMLDivElement|null>(null)
let a:echarts.ECharts|null=null,b:echarts.ECharts|null=null,observer:ResizeObserver|null=null
function render() { if (!a||!b) return; const rows=props.summary?.trend||[]; a.setOption({animation:false,color:['#4e9f7b','#dda078'],graphic:rows.length?[]:[{type:'text',left:'center',top:'40%',style:{text:'当前范围暂无记录',fill:'#a3ada0',fontSize:12}}],tooltip:{trigger:'axis'},legend:{bottom:0,itemWidth:8,itemHeight:8,textStyle:{color:'#829383',fontSize:11}},grid:{top:18,right:20,bottom:52,left:42},xAxis:{type:'category',boundaryGap:false,data:rows.map((r:any)=>r.date.slice(5)),axisLine:{lineStyle:{color:'#e7ede6'}},axisTick:{show:false},axisLabel:{color:'#97a292',fontSize:10}},yAxis:{type:'value',minInterval:1,axisLabel:{color:'#97a292',fontSize:10},splitLine:{lineStyle:{color:'#eef2ec',type:'dashed'}}},series:[{name:'完成打卡',type:'line',smooth:true,symbolSize:5,data:rows.map((r:any)=>r.completed),areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'#76b49435'},{offset:1,color:'#76b49400'}])}},{name:'缺勤',type:'line',smooth:true,symbolSize:4,data:rows.map((r:any)=>r.absent),lineStyle:{width:2,type:'dashed'}}]},true); const dist=(props.summary?.distribution||[]).map((r:any)=>({...r,name:statusNames[r.name]||r.name})); b.setOption({animation:false,color:['#79a987','#dfb576','#cd8b78','#a3bacc','#b7c895','#d9dfcf','#94c1b3'],graphic:dist.some((r:any)=>r.value>0)?[]:[{type:'text',left:'center',top:'40%',style:{text:'当前范围暂无记录',fill:'#a3ada0',fontSize:12}}],tooltip:{trigger:'item'},legend:{bottom:0,itemWidth:8,itemHeight:8,textStyle:{color:'#829383',fontSize:11}},series:[{type:'pie',stillShowZeroSum:false,radius:['49%','69%'],center:['50%','43%'],avoidLabelOverlap:true,label:{show:false},itemStyle:{borderRadius:4,borderColor:'#fff',borderWidth:3},data:dist}]},true) }
onMounted(()=>{a=echarts.init(trend.value!);b=echarts.init(distribution.value!);observer=new ResizeObserver(()=>{a?.resize();b?.resize()});observer.observe(trend.value!);observer.observe(distribution.value!);render()})
watch(()=>props.summary,async()=>{await nextTick();render()},{deep:true})
onBeforeUnmount(()=>{observer?.disconnect();a?.dispose();b?.dispose()})
</script>
<template><div class="dashboard-grid"><div class="panel chart-wrap"><div class="panel-head"><div><h2>出勤趋势</h2><p>按工作日期展示，人数以当前筛选范围为准</p></div><el-tag type="info">每日汇总</el-tag></div><div ref="trend" class="chart" role="img" aria-label="完成打卡与缺勤趋势图"/></div><div class="panel chart-wrap"><div class="panel-head"><div><h2>考勤状态分布</h2><p>每个出勤日仅归属一个主要状态</p></div></div><div ref="distribution" class="chart" role="img" aria-label="考勤状态分布图"/></div></div></template>
